<?php
require __DIR__.'/backend.php';
header('Cache-Control: no-store');
try {
    $initial=readState(db()); $initial['csrf']=$_SESSION['csrf'];
    $initialJson=json_encode($initial,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);
    session_write_close();
} catch(Throwable $e) {
    error_log('Relevamiento MySQL: '.$e->getMessage());
    http_response_code(503);
    ?><!doctype html><html lang="es"><meta charset="utf-8"><title>Conectar MySQL</title>
    <body style="font:18px Arial;max-width:720px;margin:60px auto;line-height:1.6"><h1>Falta conectar MySQL</h1>
    <p>Iniciá Apache y MySQL en XAMPP. Después importá <b>instalar.sql</b> desde phpMyAdmin.</p>
    <p>Si ya importaste la base, revisá el usuario, la contraseña y el puerto en <b>config/database.php</b>.</p>
    <p>Esta pantalla no modifica tus datos.</p><button onclick="location.reload()">Reintentar conexión</button></body></html><?php exit;
}
