      document.getElementById('choose-folder').onclick=function(){loadPrefix=document.getElementById('folder-prefix').value.trim().replace(/^"|"$/g,'');if(!loadPrefix.replace(/\\/g,'/').split('/').some(function(part){return part.toLowerCase()===IMAGE_ROOT.toLowerCase()})){notify('Pegá una ruta completa que contenga la carpeta Coleccion HLP');return}localStorage.setItem('montadas-folder-full-path',loadPrefix);document.getElementById('folder-settings').close();document.getElementById('folder').click()};
      document.getElementById('folder-filter').onchange=function(){rememberRecord(record());workingFolder=this.value;index=visibleIndexes()[0]||0;rotation={front:0,back:0};zoom={front:1,back:1};pan={front:{x:0,y:0},back:{x:0,y:0}};render()};
      document.getElementById('folder').onchange=function(e){loadFiles(e.target.files);e.target.value=''};document.getElementById('open-files').onclick=function(){document.getElementById('images').click()};document.getElementById('images').onchange=function(e){loadFiles(e.target.files);e.target.value=''};
      document.querySelectorAll('[data-view]').forEach(function(b){b.onclick=function(){view=b.dataset.view;if(view!=='both')active=view;render()}});
      var drop=document.getElementById('drop-zone');drop.ondragover=function(e){e.preventDefault()};drop.ondrop=function(e){e.preventDefault();loadFiles(e.dataTransfer.files)};
      function download(name,text,type){var u=URL.createObjectURL(new Blob([text],{type:type})),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}
      document.getElementById('export-json').onclick=function(){rememberAllRecords();var clean=records.map(cleanRecord),payload={schemaVersion:8,collection:'HLP',exportedAt:new Date().toISOString(),vocabulary:vocabulary,records:clean};download('respaldo_relevamiento_fotografias.json',JSON.stringify(payload,null,2),'application/json');notify('Respaldo de fichas y valores reutilizables descargado')};
      document.getElementById('import-json').onclick=function(){document.getElementById('json-file').click()};document.getElementById('json-file').onchange=async function(e){var file=e.target.files[0];if(!file)return;if(saving)await saving;clearTimeout(autoTimer);try{var data=JSON.parse(await file.text()),incoming=Array.isArray(data)?data:data.records;if(!Array.isArray(incoming)||!incoming.length)throw new Error('sin registros');if(!confirm('Importar reemplazará las fichas actuales por las del respaldo. ¿Continuar?'))return;if(!Array.isArray(data))mergeVocabulary(data.vocabulary);var currentImages={};records.forEach(function(r){currentImages[String(r.id).toLowerCase()]={frontUrl:r.frontUrl,backUrl:r.backUrl}});records=incoming.map(function(r){var normalized=normalizeRecord(r),images=currentImages[String(normalized.id).toLowerCase()]||{};if(!r.format)normalized.format='Carte de visite';normalized.frontUrl=images.frontUrl||'';normalized.backUrl=images.backUrl||'';return normalized});index=0;rememberAllRecords();dirty();render();var ok=await save();if(ok)notify(records.length+' fichas guardadas en MySQL')}catch(err){notify('El archivo JSON no es un respaldo válido')}e.target.value=''};
      document.getElementById('export').onclick=function(){var h=['id','carpeta','titulo','clase_imagen','representaciones','edad_aparente','caracterizacion','personas_identificadas','objetos_destacados','posicion','encuadre','fotografo','direccion_estudio','lugar','fecha','texto_frente','texto_montura','texto_dorso','sellos_marcas','numeros_pieza','codigo_coleccionista','formato','procedimiento','dimensiones','estado','notas','completo','archivo_frente','archivo_dorso','ruta_frente','ruta_dorso','modo_titulo'];function q(v){return'"'+String(v||'').replaceAll('"','""')+'"'}var rows=records.map(function(r){return[r.id,rootedFolder(r.sourcePath),r.title,r.imageClass,(r.depictedTypes||[]).join(' | '),(r.apparentAge||[]).join(' | '),(r.characterizations||[]).join(' | '),(r.identifiedPeople||[]).join(' | '),(r.objects||[]).join(' | '),r.pose,r.framing,r.photographer,r.studioAddress,r.place,r.date,r.frontText,r.mountText,r.backText,r.stamps,r.pieceNumbers,r.collectorCode,r.format,r.process,r.dimensions,r.condition,r.notes,r.complete?'sí':'no',r.frontName,r.backName,imagePath(r,r.frontName),imagePath(r,r.backName),r.titleMode==='manual'?'manual':'automático']});var csv='﻿'+[h].concat(rows).map(function(row){return row.map(q).join(';')}).join('\r\n');download('relevamiento_fotografias_montadas.csv',csv,'text/csv;charset=utf-8');notify('CSV exportado')};
      document.addEventListener('keydown',function(e){var edit=['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName);if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save()}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();record().complete=true;dirty();goto(index+1)}if(edit)return;if(e.key.toLowerCase()==='f'){view='front';active='front';render()}if(e.key.toLowerCase()==='d'){view='back';active='back';render()}if(e.key.toLowerCase()==='a'){view='both';render()}if(e.key.toLowerCase()==='r'){rotation[active]+=90;resetPan(active);renderStage()}if(e.key==='ArrowRight')goto(index+1);if(e.key==='ArrowLeft')goto(index-1)});
      var resizeTimer;window.addEventListener('resize',function(){clearTimeout(resizeTimer);resizeTimer=setTimeout(renderStage,100)});if(loadedStored)rememberAllRecords();render();document.getElementById('save').disabled=saved;document.getElementById('save').textContent='✓ MySQL conectado';
    })();
  </script>
</body>
</html>